import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    for record in reader:
        if not record:
            continue

        # Preserve malformed extra fields in the single expected column.
        value = ";".join(record)
        if not value.strip():
            continue
        if value.lstrip("\ufeff \t").startswith("#"):
            continue

        records.append(value)

    if not records:
        return {"columns": [], "rows": []}

    records[0] = records[0].lstrip("\ufeff")
    return {"columns": [records[0]], "rows": [[value] for value in records[1:]]}
